const voiceBags=new Map();const lastVoice={};function chooseVoice(pool,key){let bag=voiceBags.get(key);if(!bag||!bag.length){bag=pool.map((_,i)=>i);for(let j=bag.length-1;j>0;j--){const k=Math.floor(Math.random()*(j+1));[bag[j],bag[k]]=[bag[k],bag[j]];}if(bag.length>1&&bag[bag.length-1]===lastVoice[key]){[bag[0],bag[bag.length-1]]=[bag[bag.length-1],bag[0]];}voiceBags.set(key,bag);}const index=bag.pop();lastVoice[key]=index;return pool[index];}
function voiceScene(parts,tone){const bank=voicePools[tone]||voicePools.n;const start=chooseVoice(bank.start,tone+'start'),reaction=chooseVoice(bank.reaction,tone+'reaction'),end=chooseVoice(bank.end,tone+'end');let observed=parts.slice();observed[0]=observed[0].replace(/^Veo a /,chooseVoice(['Estoy viendo a ','Aquí hay ','Me encuentro con ','Tengo a la vista a ','Veo a '],'lead'));if(observed.length>2&&Math.random()<.5){const last=observed.pop();observed.splice(1,0,last)}const breakAt=Math.max(1,Math.min(observed.length,2));observed.splice(breakAt,0,reaction);return [start,...observed,end]}
